{{-- Choix en pastilles : chaque menu reste le champ enregistré, agent-quote.js affiche ses options en boutons (data-chips). La finition garde son menu. --}}
<div class="choice-board agent-choices" data-agent-selection>
<div class="choice-line"><span class="choice-name" id="{{ $prefix }}-type">Type de projet</span><span class="chip-field"><select data-agent-choice="project_type" data-chips aria-labelledby="{{ $prefix }}-type" name="{{ $prefix }}[project_type]">@foreach(\App\Services\AgentQuoteData::TYPES as $value=>$label)<option value="{{ $value }}" @selected($project===$value)>{{ $label }}</option>@endforeach</select></span></div>
