@endforeach
<div class="choice-line"><span class="choice-name" id="{{ $prefix }}-motor">Motorisation</span><span class="chip-field"><select data-agent-choice="motorized" data-chips aria-labelledby="{{ $prefix }}-motor" name="{{ $prefix }}[motorized]"><option value="0" @selected(empty($selection['motorized']))>Non</option><option value="1" @selected(!empty($selection['motorized']))>Oui</option></select></span></div>
