<div class="choice-line"><span class="choice-name" id="{{ $prefix }}-zone">Zone de pose</span><span class="chip-field"><select data-agent-choice="zone" data-chips aria-labelledby="{{ $prefix }}-zone" name="{{ $prefix }}[zone]"><option value="abidjan" @selected(($selection['zone'] ?? $selection['costing']['zone'] ?? 'abidjan')==='abidjan')>Abidjan</option><option value="other" @selected(($selection['zone'] ?? $selection['costing']['zone'] ?? '')==='other')>Hors Abidjan</option></select></span></div>
